# Law: lawtwin.kafka::Broker: read-committed fetches never see open or
# aborted transactions [native]
# Description: While a transaction is open its records are past the last
# stable
# offset, which read-committed consumers do not pass. Once it aborts its
# records are skipped for ever. Read-uncommitted consumers see them both
# times.
# Rationale:
# References: KIP-98
# Expansion:
# Broker: read-committed fetches never see open or aborted transactions
# [native]
# for all (t :: Text) (txid :: Text) (batch :: List
# (lawtwin.kafka.model::type::Record)) . created (_input0) (1) implies
# transactionThenRead (_input0) (_input1) (_input2) (false) = true
def test_broker_read_committed_fetches_never_see_open_or__boundary0():
    symbols = {}
    _input0 = ls.literal({"type": "Text", "units": [111]}, symbols)
    _input1 = ls.literal({"type": "Text", "units": [32]}, symbols)
    _input2 = [
        _lawspec_schema.construct(
            _schema.Named("lawtwin.kafka.model::type::Record"),
            "lawtwin.kafka.model::type::Record::Record",
            [
                _lawspec_schema.construct(
                    _schema.Named("Maybe", [_schema.Named("Bytes")]),
                    "Maybe::Nothing",
                    [],
                    64,
                    symbols,
                ),
                _lawspec_schema.construct(
                    _schema.Named("Maybe", [_schema.Named("Bytes")]),
                    "Maybe::Nothing",
                    [],
                    64,
                    symbols,
                ),
                [],
            ],
            64,
            symbols,
        ),
        _lawspec_schema.construct(
            _schema.Named("lawtwin.kafka.model::type::Record"),
            "lawtwin.kafka.model::type::Record::Record",
            [
                _lawspec_schema.construct(
                    _schema.Named("Maybe", [_schema.Named("Bytes")]),
                    "Maybe::Just",
                    [ls.bytes_literal([])],
                    64,
                    symbols,
                ),
                _lawspec_schema.construct(
                    _schema.Named("Maybe", [_schema.Named("Bytes")]),
                    "Maybe::Just",
                    [ls.bytes_literal([])],
                    64,
                    symbols,
                ),
                [],
            ],
            64,
            symbols,
        ),
    ]
    _resource0 = _lawspec_schema.from_native(
        _schema.Named("lawtwin.kafka::type::Cluster"),
        impl.connectCluster(
            ls.convert(
                ls.convert(ls.literal({"type": "Unit"}, symbols), "Unit", 64),
                "Unit",
                64,
            ),
        ),
        64,
        symbols,
    )
    try:
        ls.install_handlers(
            symbols,
            {
                (
                    "lawt"
                    "win."
                    "kafk"
                    "a::a"
                    "bili"
                    "ty::"
                    "Brok"
                    "er"
                ): impl.BrokerHandler(
                    _lawspec_schema.to_native(
                        _schema.Named("lawtwin.kafka::type::Cluster"),
                        _resource0,
                        64,
                        symbols,
                    ),
                ),
            },
        )
        if (
            _definitions.evaluate_79(
                symbols,
                _input0,
                ls.convert(1, "Int32", 64),
            )
        ):
            _lawspec_assert(
                (
                    "lawtwin.kafka::Broker: read-committed "
                    + "fetches never see open or aborted "
                    + "transactions [native] boundary 0 | "
                    + "expect transactionThenRead (_input0) "
                    + "(_input1) (_input2) (false) = "
                    + "true"
                ),
                lambda: (
                    _definitions.evaluate_345(
                        symbols,
                        _input0,
                        _input1,
                        _input2,
                        ls.convert(False, "Bool", 64),
                    )
                ),
                lambda: (ls.convert(True, "Bool", 64)),
                "Bool",
                "Bool",
            )
    finally:
        ls.validate(
            ls.unit_result(
                impl.disconnectCluster(
                    _lawspec_schema.to_native(
                        _schema.Named("lawtwin.kafka::type::Cluster"),
                        _lawspec_schema.validate(
                            _schema.Named("lawtwin.kafka::type::Cluster"),
                            _resource0,
                            64,
                            symbols,
                        ),
                        64,
                        symbols,
                    ),
                ),
            ),
            "Unit",
            64,
        )


